import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import Toastify from 'toastify-js';
import 'toastify-js/src/toastify.css';
import './style.css';
import './realtime.css';

type Log = { time: string; message: string };
type Scenario = { id:string; name:string; enabled:boolean; trigger:'interval'|'register'|'coil'; intervalMs:number; conditionAddress:number; conditionValue:number; targetArea:'register'|'coil'; targetAddress:number; targetValue:number; lastRunAt:number };
type BehaviorKind = 'digital-io'|'analog-process'|'state-machine'|'handshake'|'counter'|'alarm'|'heartbeat';
type Behavior = { id:string; name:string; kind:BehaviorKind; enabled:boolean; config:Record<string,number|string|boolean> };
type HistoryPoint = { time:string; register0:number; register1:number; register2:number; deltaD0:number; coil0:number; coil1:number; rx:number; tx:number };
type ClientConnection = {id:string;address:string;port:number;connectedAt:string;lastActivityAt:string;requests:number;bytesReceived:number;bytesSent:number};
type NetworkEndpoint = {address:string;interfaceName:string;kind:'physical'|'virtual'|'unknown'};
type DiagnosticResult = {status:'passed'|'failed';startedAt:string;finishedAt:string;durationMs:number;target:string;registerAddress:number;coilAddress:number;checks:{id:string;label:string;ok:boolean;durationMs:number;detail:string}[];error?:string};
type Confirmation = {title:string;message:string;confirmLabel:string;action:()=>void|Promise<void>};
type Machine = { id:string; name:string; manufacturer:'generic'|'delta'|'mitsubishi'; model:'generic'; template:'generic'|'delta-dvp'|'mitsubishi-fx5'; port:number; unitId:number; online:boolean; listenHost:string; networkAddresses:string[]; networkInterfaces?:NetworkEndpoint[]; clients:ClientConnection[]; lastDiagnostic?:DiagnosticResult; latencyMs:number; silent:boolean; pollIntervalMs:number; pollingEnabled:boolean; byteOrder:'AB'|'BA'; requestsReceived:number; responsesSent:number; pollingRequests:number; commandRequests:number; lastActivityAt:string; faults:{packetLossPercent:number;disconnectPercent:number;corruptReadPercent:number}; scenarios:Scenario[]; behaviors?:Behavior[]; history:HistoryPoint[]; registers:number[]; coils:boolean[]; logs:Log[] };
type Tab = 'overview'|'registers'|'coils'|'behaviors'|'connection'|'polling'|'scenarios'|'history'|'logs';
const tabs: {id:Tab; label:string}[] = [{id:'overview',label:'Visão geral'},{id:'registers',label:'Registradores'},{id:'coils',label:'Coils'},{id:'behaviors',label:'Comportamentos'},{id:'connection',label:'Conexão e clientes'},{id:'polling',label:'Polling e falhas'},{id:'scenarios',label:'Cenários avançados'},{id:'history',label:'Histórico'},{id:'logs',label:'Logs'}];

type ToastTone = 'success'|'error'|'warning'|'info';
function toast(text:string,tone:ToastTone='info'){const colors={success:'linear-gradient(135deg,#16806f,#39bda8)',error:'linear-gradient(135deg,#8f3438,#d65b60)',warning:'linear-gradient(135deg,#8a6121,#d79b3d)',info:'linear-gradient(135deg,#205f76,#318fa8)'};Toastify({text,duration:3500,close:true,gravity:'top',position:'right',stopOnFocus:true,style:{background:colors[tone],borderRadius:'8px',boxShadow:'0 12px 35px #0008'}}).showToast()}

function App() {
  const [machines,setMachines]=useState<Machine[]>([]), [selected,setSelected]=useState(''), [tab,setTab]=useState<Tab>('overview');
  const [busy,setBusy]=useState(false), [serverOk,setServerOk]=useState(false), [streamOk,setStreamOk]=useState(false), [adding,setAdding]=useState(false), [confirmation,setConfirmation]=useState<Confirmation|null>(null);
  const machine=machines.find(m=>m.id===selected) || machines[0];
  async function refresh(){ const response=await fetch('/api/machines'); if(!response.ok) throw new Error('Servidor indisponível'); const data:Machine[]=await response.json(); setMachines(data); setServerOk(true); if(!selected&&data[0]) setSelected(data[0].id); }
  useEffect(()=>{let disposed=false,socket:WebSocket|undefined,retry:ReturnType<typeof setTimeout>,fallback:ReturnType<typeof setInterval>;const patch=(id:string,change:(m:Machine)=>Machine)=>setMachines(list=>list.map(m=>m.id===id?change(m):m));const handle=(event:any)=>{if(event.type==='snapshot'){setMachines(event.machines);setSelected(current=>current||event.machines[0]?.id||'');return}if(event.type==='machine.created'){setMachines(list=>list.some(m=>m.id===event.machine.id)?list:[...list,event.machine]);return}if(event.type==='machine.deleted'){setMachines(list=>list.filter(m=>m.id!==event.machineId));setSelected(current=>current===event.machineId?'':current);return}if(event.type==='machine.updated'){patch(event.machine.id,()=>event.machine);return}if(event.type==='machine.memory'){patch(event.machineId,m=>{const key=event.area==='coil'?'coils':'registers',values=[...m[key]] as any[];event.values.forEach((v:number,i:number)=>values[event.address+i]=event.area==='coil'?Boolean(v):v);return{...m,[key]:values}});return}if(event.type==='machine.log'){patch(event.machineId,m=>({...m,logs:[event.entry,...m.logs].slice(0,200)}));return}if(event.type==='machine.traffic'){patch(event.machineId,m=>({...m,requestsReceived:event.requestsReceived,responsesSent:event.responsesSent,pollingRequests:event.pollingRequests,commandRequests:event.commandRequests,lastActivityAt:event.lastActivityAt}));return}if(event.type==='machine.clients'){patch(event.machineId,m=>({...m,clients:event.clients}));return}if(event.type==='machine.status'){patch(event.machineId,m=>({...m,online:event.online}));return}if(event.type==='machine.history'){patch(event.machineId,m=>({...m,history:[...m.history,event.point].slice(-300)}))}};const startFallback=()=>{clearInterval(fallback);fallback=setInterval(()=>void refresh().catch(()=>setServerOk(false)),5000)};const connect=()=>{if(disposed)return;socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);socket.onopen=()=>{setStreamOk(true);setServerOk(true);clearInterval(fallback)};socket.onmessage=e=>{try{handle(JSON.parse(e.data))}catch{}};socket.onclose=()=>{setStreamOk(false);startFallback();retry=setTimeout(connect,1500)};socket.onerror=()=>socket?.close()};void refresh().catch(()=>setServerOk(false));connect();return()=>{disposed=true;clearTimeout(retry);clearInterval(fallback);socket?.close()}},[]);
  async function command(body:object){if(!machine||busy)return;setBusy(true);try{const response=await fetch(`/api/machines/${machine.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error);setMachines(list=>list.map(item=>item.id===data.id?data:item));const action=(body as any).action;const messages:Record<string,string>={start:'Listener Modbus conectado.',stop:'Listener Modbus desconectado.',restart:'Estação reiniciada.',reset:'Memória da estação zerada.','clear-registers':'Holding registers zerados.','memory-bulk':'Registradores gravados.','memory':'Memória atualizada.',settings:'Configuração aplicada.',template:'Fabricante e modelo atualizados.',rename:'Nome da estação atualizado.',faults:'Configuração de falhas aplicada.','behavior-create':'Comportamento adicionado.','behavior-save':'Comportamento salvo.','behavior-delete':'Comportamento removido.','scenario-save':'Cenário salvo.','scenario-delete':'Cenário removido.','scenario-run':'Cenário executado.','clear-history':'Histórico limpo.','clear-logs':'Logs limpos.',diagnostic:'Autoteste Modbus concluído.','firewall-open':'Regra de firewall verificada.'};if(messages[action])toast(messages[action],'success');return data}catch(e){toast((e as Error).message,'error')}finally{setBusy(false)}}
  async function removeMachine(target:Machine){setBusy(true);try{const response=await fetch(`/api/machines/${target.id}`,{method:'DELETE'});if(!response.ok)throw new Error((await response.json()).error);setMachines(list=>list.filter(item=>item.id!==target.id));setSelected(current=>current===target.id?'':current);toast(`Estação “${target.name}” removida.`,'success')}catch(e){toast((e as Error).message,'error')}finally{setBusy(false)}}
  function confirm(options:Confirmation){setConfirmation(options)}
  return <div className="app-shell"><header><div className="brand"><span className="brand-mark">CLP</span><div><strong>Simulator</strong><small>Modbus TCP Workbench</small></div></div><div className="header-status"><span className={`dot ${serverOk?'on':'off'}`}/>{streamOk?'Tempo real · WebSocket':serverOk?'Conectado · fallback HTTP':'Painel indisponível'}</div></header>
    <div className="layout"><aside><div className="aside-title"><span>CLPs cadastradas</span><button className="icon-button" title="Cadastrar CLP" onClick={()=>setAdding(true)}>＋</button></div><div className="machine-list">{machines.map(m=><div className="machine-row" key={m.id}><button className={`machine-card ${m.id===machine?.id?'selected':''}`} onClick={()=>setSelected(m.id)}><span className={`machine-icon ${m.online?'online':''}`}>▣</span><span><strong>{m.name}</strong><small>{m.manufacturer==='delta'?'DELTA · GENÉRICO':m.manufacturer==='mitsubishi'?'MITSUBISHI · GENÉRICO':'GENÉRICO'} · :{m.port}</small></span><i className={m.online?'ok':'fail'}>{m.online?'ONLINE':'OFFLINE'}</i></button><button className="machine-delete" title={`Excluir ${m.name}`} aria-label={`Excluir ${m.name}`} onClick={()=>confirm({title:`Excluir “${m.name}”?`,message:`O listener da porta ${m.port} será encerrado e o cadastro será removido. Esta ação não pode ser desfeita.`,confirmLabel:'Sim, excluir estação',action:()=>removeMachine(m)})}>×</button></div>)}</div><button className="add-machine" onClick={()=>setAdding(true)}>＋ Nova CLP</button><div className="aside-foot"><span>Servidor local</span><code>127.0.0.1:3100</code></div></aside>
      <main>{machine?<><div className="page-head"><div><div className="breadcrumbs">BANCADA / {machine.id.toUpperCase()}</div><EditableStationName key={`${machine.id}-${machine.name}`} machine={machine} busy={busy} command={command}/><p>Servidor Modbus TCP em <code>{machine.networkAddresses?.[0]||machine.listenHost}:{machine.port}</code> · Unit ID {machine.unitId}</p></div><div className="head-actions"><TemplateSelector m={machine} busy={busy} command={command}/><button className={machine.online?'danger':'primary'} disabled={busy} onClick={()=>void command({action:machine.online?'stop':'start'})}>{machine.online?'Desconectar':'Conectar'}</button></div></div>
        <nav className="tabs">{tabs.map(t=><button key={t.id} className={tab===t.id?'active':''} onClick={()=>setTab(t.id)}>{t.label}</button>)}</nav>
        {tab==='overview'&&<Overview m={machine} busy={busy} command={command}/>} {tab==='registers'&&<Registers key={`${machine.id}-${machine.byteOrder}-${machine.manufacturer}-${machine.model}`} m={machine} busy={busy} command={command} confirm={confirm}/>} {tab==='coils'&&<Coils m={machine} busy={busy} command={command}/>} {tab==='behaviors'&&<Behaviors key={machine.id} m={machine} busy={busy} command={command} confirm={confirm}/>} {tab==='connection'&&<><RenameStation key={`rename-${machine.id}-${machine.name}`} m={machine} busy={busy} command={command}/><Connection key={machine.id} m={machine} busy={busy} command={command}/><FirewallAction m={machine} busy={busy} command={command} confirm={confirm}/></>} {tab==='polling'&&<><Polling key={machine.id} m={machine} busy={busy} command={command}/><Faults key={`faults-${machine.id}`} m={machine} busy={busy} command={command}/></>} {tab==='scenarios'&&<Scenarios key={machine.id} m={machine} busy={busy} command={command}/>} {tab==='history'&&<History m={machine} busy={busy} command={command}/>} {tab==='logs'&&<Logs m={machine} busy={busy} command={command}/>}
      </>:<div className="empty">Aguardando o servidor…</div>}</main></div>{adding&&<NewMachine close={()=>setAdding(false)} created={async id=>{setAdding(false);setSelected(id);await refresh();toast('Nova CLP cadastrada e inicializada.','success')}}/>}{confirmation&&<ConfirmModal confirmation={confirmation} busy={busy} close={()=>setConfirmation(null)} execute={async()=>{await confirmation.action();setConfirmation(null)}}/>}</div>;
}

function Overview({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const diagnostic=m.lastDiagnostic;return <div className="content"><div className="summary-grid"><Stat label="Estado do listener" value={m.online?'Conectado':'Desconectado'} tone={m.online?'green':'red'} sub={`Porta ${m.port} · Unit ${m.unitId}`}/><Stat label="Clientes ativos" value={String(m.clients?.length||0)} tone={m.clients?.length?'green':''} sub="Sessões TCP neste instante"/><Stat label="Requisições recebidas" value={String(m.requestsReceived)} sub="Desde que o processo iniciou"/><Stat label="Respostas enviadas" value={String(m.responsesSent)} sub={m.silent?'Respostas silenciadas':'Operação normal'}/></div><div className="two-cols"><Panel title="Diagnóstico rápido" extra={<span className={`badge ${diagnostic?(diagnostic.status==='passed'?'green':'red'):(m.online?'green':'red')}`}>{diagnostic?(diagnostic.status==='passed'?'APROVADO':'FALHOU'):(m.online?'PRONTO':'ATENÇÃO')}</span>}><div className="check-list"><Check ok={m.online} text="Servidor Modbus TCP escutando" detail={`${m.listenHost}:${m.port}`}/><Check ok={!m.silent} text="Respostas Modbus habilitadas" detail={m.silent?'Modo timeout proposital ativo':'Clientes recebem confirmação'}/>{diagnostic?.checks.map(item=><Check key={item.id} ok={item.ok} text={`${item.label} · ${item.durationMs} ms`} detail={item.detail}/>)}</div>{diagnostic&&<p className="diagnostic-summary">Último teste: {new Date(diagnostic.finishedAt).toLocaleString('pt-BR')} · {diagnostic.durationMs} ms · memória temporária HR {diagnostic.registerAddress}–{diagnostic.registerAddress+1} / coil {diagnostic.coilAddress}</p>}<button className="primary" disabled={busy||!m.online} onClick={()=>void command({action:'diagnostic'})}>{busy?'Executando…':'Executar autoteste Modbus'}</button></Panel><Panel title="Mapa em destaque" extra={<span className="badge">{m.byteOrder}</span>}><div className="memory-preview"><div><span>Coil 0</span><b className={m.coils[0]?'true':''}>{m.coils[0]?'1 / TRUE':'0 / FALSE'}</b></div><div><span>Coil 1</span><b className={m.coils[1]?'true':''}>{m.coils[1]?'1 / TRUE':'0 / FALSE'}</b></div><div><span>Holding 0</span><b>{m.registers[0]??0}</b></div><div><span>Holding 1</span><b>{m.registers[1]??0}</b></div></div></Panel></div></div>}
function Stat({label,value,sub,tone=''}:{label:string;value:string;sub:string;tone?:string}){return <div className="stat"><span>{label}</span><strong className={tone}>{value}</strong><small>{sub}</small></div>}
function Panel({title,extra,children}:{title:string;extra?:React.ReactNode;children:React.ReactNode}){return <section><div className="panel-title"><h2>{title}</h2>{extra}</div>{children}</section>}
function Check({ok,text,detail}:{ok:boolean;text:string;detail:string}){return <div className="check-row"><span className={ok?'pass':'warn'}>{ok?'✓':'!'}</span><div><strong>{text}</strong><small>{detail}</small></div></div>}

function TemplateSelector({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){return <div className="quick-template"><label>Fabricante<select disabled={busy} value={m.manufacturer} onChange={e=>void command({action:'template',manufacturer:e.target.value,model:'generic'})}><option value="generic">Genérico</option><option value="delta">Delta</option><option value="mitsubishi">Mitsubishi</option></select></label><label>Modelo<select disabled value={m.model}><option value="generic">Genérico</option></select></label></div>}

function Registers({m,busy,command,confirm}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>;confirm:(options:Confirmation)=>void}){
  const initial=m.manufacturer==='delta'?4096:0;
  const[start,setStart]=useState(initial),[count,setCount]=useState(16),[writeStart,setWriteStart]=useState(initial),[input,setInput]=useState('0');
  const swap=(v:number)=>((v&255)<<8)|(v>>8);
  const ascii=(word:number)=>[(word>>8)&255,word&255].map(byte=>byte>=32&&byte<=126?String.fromCharCode(byte):'·').join('');
  const rows=useMemo(()=>Array.from({length:Math.min(count,64)},(_,i)=>{const address=start+i,raw=m.registers[address]??0,word=m.byteOrder==='BA'?swap(raw):raw,alias=m.manufacturer==='delta'&&address>=4096?`D${address-4096}`:m.manufacturer==='mitsubishi'&&address<8000?`D${address}`:`HR${address}`;return{address,word,alias}}),[m.registers,m.byteOrder,m.manufacturer,start,count]);
  function changeInput(value:string){if(/[^0-9\s,;]/.test(value))toast('Valores decimais aceitam somente números e os separadores vírgula, espaço ou ponto e vírgula.','warning');setInput(value.replace(/[^0-9\s,;]/g,''))}
  async function write(e:React.FormEvent){e.preventDefault();let values=input.split(/[\s,;]+/).filter(Boolean).map(Number);if(!values.length){toast('Informe ao menos um valor decimal.','warning');return}if(values.some(v=>!Number.isInteger(v)||v<0||v>65535)){toast('Cada registrador deve conter um inteiro entre 0 e 65535.','warning');return}if(writeStart+values.length>8192){toast('A escrita ultrapassa o último holding register.','warning');return}if(m.byteOrder==='BA')values=values.map(swap);await command({action:'memory-bulk',address:writeStart,values})}
  const mapLabel=m.manufacturer==='delta'?'Delta · modelo Genérico · D0 = 4096':m.manufacturer==='mitsubishi'?'Mitsubishi · modelo Genérico · D0 = 0':'Fabricante e modelo genéricos';
  return <div className="content"><div className="toolbar"><label>Endereço inicial<input type="number" min="0" max="8191" value={start} onChange={e=>setStart(+e.target.value)}/></label><label>Quantidade<input type="number" min="1" max="64" value={count} onChange={e=>setCount(+e.target.value)}/></label><span className="order-chip">{mapLabel} · bytes <b>{m.byteOrder}</b></span><button className="danger" disabled={busy} onClick={()=>confirm({title:'Zerar todos os holding registers?',message:'Os 8.192 holding/input registers desta estação receberão o valor zero. Coils e configurações serão preservados.',confirmLabel:'Zerar registradores',action:()=>command({action:'clear-registers'})})}>Zerar holding registers</button></div><div className="register-layout"><section className="table-panel"><div className="panel-title"><h2>Holding registers</h2><span className="muted">FC03 / FC04</span></div><div className="data-table"><div className="tr head"><span>Endereço</span><span>Decimal</span><span>Hex</span><span>Binário</span><span>ASCII</span></div>{rows.map(r=><div className="tr" key={r.address}><code>{r.alias}<small>{r.address}</small></code><strong>{r.word}</strong><code>0x{r.word.toString(16).padStart(4,'0').toUpperCase()}</code><code>{r.word.toString(2).padStart(16,'0')}</code><code className="ascii-cell" title="Um caractere ASCII por byte; bytes não imprimíveis aparecem como ·">{ascii(r.word)}</code></div>)}</div></section><Panel title="Escrever registradores"><form onSubmit={write} className="stack"><label>Endereço inicial<input type="number" min="0" max="8191" value={writeStart} onChange={e=>setWriteStart(+e.target.value)}/></label><label>Valores decimais<textarea inputMode="numeric" rows={5} value={input} onChange={e=>changeInput(e.target.value)} placeholder="10, 20, 30"/></label><p className="help">Aceita inteiros de 0 a 65535 separados por vírgula, espaço ou ponto e vírgula. A coluna ASCII mostra um caractere imprimível por byte.</p><button className="primary" disabled={busy}>Gravar com FC16</button></form></Panel></div></div>
}

function Coils({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const base=m.manufacturer==='delta'?2048:m.manufacturer==='mitsubishi'?8192:0;const set=(address:number,value:boolean)=>command({action:'memory',area:'coil',address,value:Number(value)});const mapped=m.manufacturer!=='generic';return <div className="content"><div className="two-cols"><Panel title="Coils de teste" extra={<span className="muted">FC01 / FC05</span>}>{[0,1].map(a=><div className="coil-feature" key={a}><div><span>COIL {a}</span><strong>SINAL DE TESTE {a}</strong><small>Endereço {a} · {m.coils[a]?'TRUE':'FALSE'}</small></div><button className={`toggle ${m.coils[a]?'checked':''}`} disabled={busy} onClick={()=>void set(a,!m.coils[a])}><i/></button></div>)}</Panel><Panel title={m.manufacturer==='delta'?'Delta · Genérico · M0–M15':m.manufacturer==='mitsubishi'?'Mitsubishi · Genérico · M0–M15':'Banco de coils'}><div className="coil-grid">{Array.from({length:16},(_,offset)=>{const address=base+offset;return <button key={address} className={m.coils[address]?'active':''} disabled={busy} onClick={()=>void set(address,!m.coils[address])}><span>{mapped?`M${offset}`:address}</span><b>{m.coils[address]?'1':'0'}</b></button>})}</div><p className="help">{m.manufacturer==='delta'?'O modelo genérico Delta usa M0 no offset 2048.':m.manufacturer==='mitsubishi'?'O modelo genérico Mitsubishi usa M0 no offset 8192 e mantém a área Y no início dos coils.':'Clique em uma posição para alternar o estado. FC02 espelha os mesmos valores.'}</p></Panel></div></div>}

const behaviorCatalog:Record<BehaviorKind,{label:string;description:string}>={
  'digital-io':{label:'Entrada e saída digital',description:'Gera pulsos periódicos para sensores, relés e fins de curso.'},
  'analog-process':{label:'Processo analógico',description:'Simula nível, pressão, temperatura ou velocidade em rampa, seno ou ruído.'},
  'state-machine':{label:'Máquina de estados',description:'Publica Parado, Iniciando, Executando, Finalizando e Falha.'},
  handshake:{label:'Ciclo e handshake',description:'Executa o fluxo genérico Request, Busy, Done, Ack e Error.'},
  counter:{label:'Contador e encoder',description:'Conta bordas de subida, aplica passo, rollover e reset.'},
  alarm:{label:'Alarmes e intertravamentos',description:'Monitora limites e suporta alarme momentâneo ou memorizado.'},
  heartbeat:{label:'Heartbeat e watchdog',description:'Publica contador de vida e sinal de saúde da integração.'}
};
type BehaviorField={key:string;label:string;type?:'number'|'boolean'|'waveform';min?:number;max?:number};
const behaviorFields:Record<BehaviorKind,BehaviorField[]>={
  'digital-io':[{key:'address',label:'Coil de saída',min:0,max:16383},{key:'onMs',label:'Tempo ligado (ms)',min:100,max:86400000},{key:'offMs',label:'Tempo desligado (ms)',min:100,max:86400000}],
  'analog-process':[{key:'address',label:'Holding register',min:0,max:8191},{key:'waveform',label:'Forma de onda',type:'waveform'},{key:'min',label:'Valor mínimo',min:0,max:65535},{key:'max',label:'Valor máximo',min:0,max:65535},{key:'periodMs',label:'Período (ms)',min:100,max:86400000}],
  'state-machine':[{key:'commandCoil',label:'Coil de comando',min:0,max:16383},{key:'faultCoil',label:'Coil de falha',min:0,max:16383},{key:'stateRegister',label:'Registro de estado',min:0,max:8191},{key:'startMs',label:'Tempo de partida (ms)',min:100,max:86400000},{key:'stopMs',label:'Tempo de parada (ms)',min:100,max:86400000}],
  handshake:[{key:'requestCoil',label:'Request coil',min:0,max:16383},{key:'busyCoil',label:'Busy coil',min:0,max:16383},{key:'doneCoil',label:'Done coil',min:0,max:16383},{key:'ackCoil',label:'Ack coil',min:0,max:16383},{key:'errorCoil',label:'Error coil',min:0,max:16383},{key:'cycleMs',label:'Duração do ciclo (ms)',min:100,max:86400000}],
  counter:[{key:'sourceCoil',label:'Coil de pulso',min:0,max:16383},{key:'resetCoil',label:'Coil de reset',min:0,max:16383},{key:'targetRegister',label:'Registro contador',min:0,max:8191},{key:'step',label:'Incremento',min:1,max:65535},{key:'max',label:'Valor máximo',min:0,max:65535}],
  alarm:[{key:'sourceRegister',label:'Registro monitorado',min:0,max:8191},{key:'alarmCoil',label:'Coil de alarme',min:0,max:16383},{key:'ackCoil',label:'Coil de reconhecimento',min:0,max:16383},{key:'low',label:'Limite baixo',min:0,max:65535},{key:'high',label:'Limite alto',min:0,max:65535},{key:'latched',label:'Alarme memorizado',type:'boolean'}],
  heartbeat:[{key:'register',label:'Registro heartbeat',min:0,max:8191},{key:'healthyCoil',label:'Coil de saúde',min:0,max:16383},{key:'intervalMs',label:'Intervalo (ms)',min:100,max:86400000},{key:'max',label:'Valor máximo',min:0,max:65535}]
};
function behaviorMap(b:Behavior){const c=b.config;switch(b.kind){case'digital-io':return`Coil ${c.address}`;case'analog-process':return`Holding ${c.address}`;case'state-machine':return`Coils ${c.commandCoil}/${c.faultCoil} · Holding ${c.stateRegister}`;case'handshake':return`Coils ${c.requestCoil}/${c.busyCoil}/${c.doneCoil}/${c.ackCoil}/${c.errorCoil}`;case'counter':return`Coils ${c.sourceCoil}/${c.resetCoil} · Holding ${c.targetRegister}`;case'alarm':return`Holding ${c.sourceRegister} · Coils ${c.alarmCoil}/${c.ackCoil}`;case'heartbeat':return`Holding ${c.register} · Coil ${c.healthyCoil}`}}
function behaviorWrites(b:Behavior){const c=b.config;switch(b.kind){case'digital-io':return[`c:${c.address}`];case'analog-process':return[`r:${c.address}`];case'state-machine':return[`r:${c.stateRegister}`];case'handshake':return[`c:${c.busyCoil}`,`c:${c.doneCoil}`,`c:${c.errorCoil}`];case'counter':return[`r:${c.targetRegister}`];case'alarm':return[`c:${c.alarmCoil}`];case'heartbeat':return[`r:${c.register}`,`c:${c.healthyCoil}`]}}
function Behaviors({m,busy,command,confirm}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>;confirm:(options:Confirmation)=>void}){const[kind,setKind]=useState<BehaviorKind>('digital-io'),behaviors=m.behaviors||[];const writes=new Map<string,string[]>();for(const b of behaviors)for(const address of behaviorWrites(b)){const ids=writes.get(address)||[];ids.push(b.id);writes.set(address,ids)}const conflicts=new Set([...writes.values()].filter(ids=>ids.length>1).flat());return <div className="content behavior-page"><section className="behavior-intro"><div><span className="eyebrow">SIMULAÇÃO COMBINÁVEL</span><h2>Comportamentos da estação</h2><p>Ative vários módulos ao mesmo tempo. Fabricante e modelo definem o mapa; estes módulos definem como os sinais se comportam.</p></div><form onSubmit={e=>{e.preventDefault();void command({action:'behavior-create',kind})}}><select value={kind} onChange={e=>setKind(e.target.value as BehaviorKind)}>{Object.entries(behaviorCatalog).map(([key,item])=><option key={key} value={key}>{item.label}</option>)}</select><button className="primary" disabled={busy}>Adicionar comportamento</button></form></section>{conflicts.size>0&&<div className="behavior-warning">Atenção: existem comportamentos escrevendo no mesmo endereço. A última escrita de cada ciclo prevalece.</div>}<div className="behavior-list">{behaviors.length?behaviors.map(b=><BehaviorEditor key={`${b.id}-${JSON.stringify(b)}`} behavior={b} conflict={conflicts.has(b.id)} busy={busy} command={command} confirm={confirm}/>):<div className="behavior-empty"><b>Nenhum comportamento automático</b><span>A memória continua disponível para leitura e escrita manual. Adicione um módulo quando precisar simular sinais.</span></div>}</div><details className="behavior-catalog"><summary>Ver catálogo e finalidade dos módulos</summary><div>{Object.entries(behaviorCatalog).map(([key,item])=><article key={key}><b>{item.label}</b><span>{item.description}</span></article>)}</div></details></div>}
function BehaviorEditor({behavior,conflict,busy,command,confirm}:{behavior:Behavior;conflict:boolean;busy:boolean;command:(b:object)=>Promise<any>;confirm:(options:Confirmation)=>void}){const[form,setForm]=useState<Behavior>({...behavior,config:{...behavior.config}});const save=(patch:Partial<Behavior>={})=>command({action:'behavior-save',behavior:{...form,...patch}});return <section className={`behavior-card ${!form.enabled?'disabled':''} ${conflict?'conflict':''}`}><div className="behavior-card-head"><div><span className="behavior-kind">{behaviorCatalog[form.kind].label}</span><input aria-label="Nome do comportamento" maxLength={80} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><small>{behaviorCatalog[form.kind].description}</small></div><label className="behavior-enabled"><input type="checkbox" checked={form.enabled} onChange={e=>{const enabled=e.target.checked;setForm({...form,enabled});void save({enabled})}}/><span>{form.enabled?'Ativo':'Pausado'}</span></label></div><div className="behavior-fields">{behaviorFields[form.kind].map(field=><label key={field.key}>{field.label}{field.type==='boolean'?<select value={String(form.config[field.key])} onChange={e=>setForm({...form,config:{...form.config,[field.key]:e.target.value==='true'}})}><option value="false">Não</option><option value="true">Sim</option></select>:field.type==='waveform'?<select value={String(form.config[field.key])} onChange={e=>setForm({...form,config:{...form.config,[field.key]:e.target.value}})}><option value="ramp">Rampa</option><option value="sine">Senoidal</option><option value="random">Aleatória</option></select>:<input type="number" min={field.min} max={field.max} value={Number(form.config[field.key])} onChange={e=>setForm({...form,config:{...form.config,[field.key]:+e.target.value}})}/>}</label>)}</div><div className="behavior-card-foot"><span className={conflict?'red':''}>{conflict?'⚠ Conflito · ':''}{behaviorMap(form)}</span><div><button disabled={busy||!form.name.trim()} className="primary" onClick={()=>void save()}>Salvar</button><button className="danger" disabled={busy} onClick={()=>confirm({title:`Excluir “${form.name}”?`,message:'O comportamento será removido desta estação. Os valores atuais da memória serão preservados.',confirmLabel:'Excluir comportamento',action:()=>command({action:'behavior-delete',id:form.id})})}>Excluir</button></div></div></section>}

function Clients({m,embedded=false}:{m:Machine;embedded?:boolean}){const[copied,setCopied]=useState('');const fallback=(m.networkAddresses?.length?m.networkAddresses:[m.listenHost]).map(address=>({address,interfaceName:'Interface não identificada',kind:'unknown' as const}));const interfaces=m.networkInterfaces?.length?m.networkInterfaces:fallback;const endpoints=interfaces.map(item=>({...item,endpoint:`${item.address}:${m.port}`}));async function copy(endpoint:string){await navigator.clipboard.writeText(endpoint);setCopied(endpoint);setTimeout(()=>setCopied(''),1800)}const kindLabel={physical:'Físico provável',virtual:'Virtual / VPN',unknown:'Não identificado'};return <div className={`${embedded?'':'content '}clients-page`}><section className="remote-access"><div><span className="eyebrow">ACESSO PELA REDE LOCAL</span><h2>Conectar outro computador</h2><p>Escolha preferencialmente uma interface física da mesma rede do cliente. A classificação é estimada pelo nome do adaptador informado pelo sistema operacional.</p></div><div className="endpoint-list">{endpoints.map(item=><div className="endpoint-row" key={item.endpoint}><div><code>{item.endpoint}</code><small className={item.kind}>{kindLabel[item.kind]} · {item.interfaceName}</small></div><button onClick={()=>void copy(item.endpoint)}>{copied===item.endpoint?'Copiado ✓':'Copiar'}</button></div>)}</div>{m.listenHost!=='0.0.0.0'&&<div className="behavior-warning">O listener está limitado a {m.listenHost}. Configure <code>MODBUS_HOST=0.0.0.0</code> e reinicie o simulador para aceitar outros computadores.</div>}</section><div className="summary-grid client-stats"><Stat label="Clientes ativos" value={String(m.clients?.length||0)} tone={m.clients?.length?'green':''} sub="Sessões abertas agora"/><Stat label="Unit ID" value={String(m.unitId)} sub="Identificador Modbus"/><Stat label="Polling provável" value={String(m.pollingRequests||0)} sub="Leituras FC01–FC04"/><Stat label="Comandos" value={String(m.commandRequests||0)} sub="Escritas FC05/06/16"/></div><section className="client-panel"><div className="panel-title"><div><h2>Clientes conectados em tempo real</h2><p>Atualização automática por WebSocket. Conexões e frames também aparecem na aba Logs.</p></div><span className={`badge ${m.clients?.length?'green':''}`}>{m.clients?.length||0} ATIVO(S)</span></div>{m.clients?.length?<div className="client-table"><div className="client-row head"><span>Cliente</span><span>Conectado desde</span><span>Última atividade</span><span>Requisições</span><span>Tráfego</span></div>{m.clients.map(client=><div className="client-row" key={client.id}><code>{client.address}:{client.port}</code><span>{new Date(client.connectedAt).toLocaleTimeString('pt-BR')}</span><span>{new Date(client.lastActivityAt).toLocaleTimeString('pt-BR')}</span><strong>{client.requests}</strong><small>RX {formatBytes(client.bytesReceived)} · TX {formatBytes(client.bytesSent)}</small></div>)}</div>:<div className="no-logs">Nenhum cliente Modbus conectado. O listener continua aguardando em {endpoints.map(item=>item.endpoint).join(' ou ')}.</div>}<p className="help network-help">Se o cliente não alcançar o endpoint, confirme a rota de rede e a liberação da porta {m.port} no firewall do computador do simulador.</p></section></div>}
function formatBytes(value:number){return value<1024?`${value} B`:`${(value/1024).toFixed(1)} KB`}

function Connection({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const manufacturerName=m.manufacturer==='delta'?'Delta':m.manufacturer==='mitsubishi'?'Mitsubishi':'Genérico';const templateHelp=m.manufacturer==='delta'?'Mapa base do fabricante: D0 no holding 4096 e M0 no coil 2048.':m.manufacturer==='mitsubishi'?'Mapa base do fabricante: D0 no holding 0 e M0 no coil 8192.':'Endereços Modbus exibidos sem aliases de fabricante.';const activity=m.logs.filter(log=>/^(RX|TX|ERR)|Cliente Modbus|Modbus disponível|Conexão desligada|Socket:|Servidor:/.test(log.message)).slice(0,14);return <div className="content connection-page"><section className="template-bar"><div><span className="eyebrow">TEMPLATE DE FABRICANTE E MODELO</span><h2>{manufacturerName} · Modelo genérico</h2><p>{templateHelp} Modelos específicos serão adicionados conforme a necessidade.</p></div><div className="template-selects"><label>Fabricante<select disabled={busy} value={m.manufacturer} onChange={e=>void command({action:'template',manufacturer:e.target.value,model:'generic'})}><option value="generic">Genérico</option><option value="delta">Delta</option><option value="mitsubishi">Mitsubishi</option></select></label><label>Modelo<select disabled value={m.model}><option value="generic">Genérico</option></select></label></div></section><div className="two-cols"><Panel title="Servidor Modbus desta CLP" extra={<span className={`badge ${m.online?'green':'red'}`}>{m.online?'CONECTADO':'OFFLINE'}</span>}><div className="connection-card"><span>MODBUS TCP</span><strong>{m.listenHost}:{m.port}</strong><small>Unit ID {m.unitId} · resposta normal para funções suportadas · exceção para função inválida</small></div><div className="button-row"><button className="primary" disabled={busy||m.online} onClick={()=>void command({action:'start'})}>Conectar</button><button disabled={busy||!m.online} onClick={()=>void command({action:'stop'})}>Desconectar</button><button disabled={busy} onClick={()=>void command({action:'restart'})}>Reiniciar</button></div></Panel><Panel title="Áreas disponíveis"><div className="check-list"><Check ok text="Coils e discrete inputs" detail="16.384 posições digitais"/><Check ok text="Holding e input registers" detail="8.192 words de 16 bits"/><Check ok text="Respostas protocolares" detail="Resposta da função ou exceção Modbus adequada"/></div><p className="help">O cliente pode ler e escrever diretamente sem ativar um comportamento. Comportamentos são opcionais e podem sobrescrever os mesmos endereços.</p></Panel></div><section className="connection-activity"><div className="panel-title"><div><h2>Atividade da conexão</h2><p>Recebimentos, respostas, clientes e eventos do listener em tempo real.</p></div><span className={`badge ${m.online?'green':'red'}`}>{m.online?'AO VIVO':'DESCONECTADO'}</span></div><div className="connection-metrics"><div><span>Estado</span><strong className={m.online?'green':'red'}>{m.online?'Escutando':'Offline'}</strong><small>{m.listenHost}:{m.port}</small></div><div><span>Clientes</span><strong>{m.clients?.length||0}</strong><small>Sessões TCP ativas</small></div><div><span>Polling provável</span><strong className="rx-value">{m.pollingRequests||0}</strong><small>Leituras FC01–FC04</small></div><div><span>Comandos</span><strong className="green">{m.commandRequests||0}</strong><small>Escritas FC05/06/16</small></div><div><span>Respostas</span><strong>{m.responsesSent}</strong><small>Transmitidas ao cliente</small></div></div><div className="connection-feed"><div className="terminal-head"><span>HORA</span><span title="RX: recebido · TX: enviado · ERR: erro · SYS: sistema">TIPO ⓘ</span><span>ATIVIDADE</span></div>{activity.length?activity.map((log,index)=>{const type=log.message.slice(0,3).trim(),known=['RX','TX','ERR','SYS'].includes(type),shown=known?type:'SYS';return <div className="log-line" key={`${log.time}-${index}`}><time>{new Date(log.time).toLocaleTimeString('pt-BR',{hour12:false})}</time><b title={logTypeTitle(shown)} className={shown.toLowerCase()}>{shown}</b><code>{known?log.message.slice(type.length).trim():log.message}</code></div>}):<div className="connection-empty">Aguardando atividade Modbus nesta estação.</div>}</div><p className="help connection-hint">A aba Logs mantém o histórico completo e permite exportar os eventos. A exclusão da estação fica no botão × ao lado dela na barra lateral.</p></section><Clients m={m} embedded/></div>}

function FirewallAction({m,busy,command,confirm}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>;confirm:(options:Confirmation)=>void}){return <div className="content firewall-content"><section className="firewall-action"><div><span className="eyebrow">FIREWALL DO WINDOWS</span><h2>Acesso externo à porta {m.port}</h2><p>A aplicação verifica se a regra própria já existe. Se estiver ausente, o Windows solicitará autorização de administrador e criará somente a entrada TCP desta estação.</p></div><button disabled={busy} onClick={()=>confirm({title:`Verificar e liberar a porta ${m.port}?`,message:'Se a regra ainda não existir, o Windows exibirá a confirmação de administrador. Nenhuma regra existente será removida ou alterada.',confirmLabel:'Verificar e liberar',action:()=>command({action:'firewall-open'})})}>Verificar/liberar firewall</button></section></div>}

function Polling({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const[form,set]=useState({silent:m.silent,latencyMs:m.latencyMs,pollIntervalMs:m.pollIntervalMs,pollingEnabled:m.pollingEnabled,byteOrder:m.byteOrder});return <div className="content"><div className="two-cols"><Panel title="Polling e temporização"><form className="form-grid" onSubmit={e=>{e.preventDefault();void command({action:'settings',...form})}}><label>Intervalo do painel (ms)<input type="number" min="200" max="60000" value={form.pollIntervalMs} onChange={e=>set({...form,pollIntervalMs:+e.target.value})}/></label><label>Latência Modbus simulada (ms)<input type="number" min="0" max="10000" value={form.latencyMs} onChange={e=>set({...form,latencyMs:+e.target.value})}/></label><label>Ordem de bytes<select value={form.byteOrder} onChange={e=>set({...form,byteOrder:e.target.value as 'AB'|'BA'})}><option value="AB">AB · high byte primeiro</option><option value="BA">BA · low byte primeiro</option></select></label><label className="switch-line"><input type="checkbox" checked={form.pollingEnabled} onChange={e=>set({...form,pollingEnabled:e.target.checked})}/><span><b>Polling automático</b><small>Atualizar painel continuamente</small></span></label><label className="switch-line"><input type="checkbox" checked={form.silent} onChange={e=>set({...form,silent:e.target.checked})}/><span><b>Silenciar respostas</b><small>Simular timeout do cliente</small></span></label><button className="primary" disabled={busy}>Aplicar configuração</button></form></Panel><Panel title="Estimativa de carga"><div className="load-ring"><strong>{form.pollingEnabled?Math.round(60000/form.pollIntervalMs):0}</strong><span>consultas/min</span></div><p className="help">Intervalos entre 500 e 2.000 ms funcionam bem para supervisão. Para testes de estresse, reduza gradualmente e acompanhe RX/TX na aba Logs.</p><div className="formula"><span>Byte order</span><code>{form.byteOrder==='AB'?'[A][B] → 0x4142':'[B][A] → 0x4241'}</code></div></Panel></div></div>}

function logTypeTitle(type:string){return type==='RX'?'RX · dado recebido do cliente':type==='TX'?'TX · resposta enviada ao cliente':type==='ERR'?'ERR · erro ou falha simulada':'SYS · evento do sistema ou da conexão'}
function Logs({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const[filter,setFilter]=useState('ALL');const polling=(message:string)=>/FC0[1-4]/.test(message),commandLog=(message:string)=>/FC(05|06|15|16)/.test(message);const logs=m.logs.filter(l=>filter==='ALL'||filter==='POLLING'?filter==='ALL'||polling(l.message):filter==='COMMANDS'?commandLog(l.message):l.message.startsWith(filter));const json=()=>download(`${m.id}-logs.json`,'application/json',JSON.stringify(logs,null,2));const csv=()=>download(`${m.id}-logs.csv`,'text/csv;charset=utf-8','data_hora,tipo,mensagem\n'+logs.map(l=>{const type=['RX','TX','ERR','SYS'].find(t=>l.message.startsWith(t))||'SYS';return[l.time,type,l.message].map(v=>`"${v.replace(/"/g,'""')}"`).join(',')}).join('\n'));return <div className="content"><section className="log-panel"><div className="panel-title"><div><h2>Tráfego e eventos</h2><p>{m.logs.length} eventos em memória · {m.pollingRequests||0} leitura(s) de polling provável · {m.commandRequests||0} comando(s)</p></div><div className="log-actions"><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">Todos</option><option value="POLLING">Polling · FC01–FC04</option><option value="COMMANDS">Comandos · FC05/06/15/16</option><option value="RX">Recebidos · RX</option><option value="TX">Enviados · TX</option><option value="ERR">Erros</option><option value="SYS">Sistema</option></select><button onClick={csv}>CSV</button><button onClick={json}>JSON</button><button disabled={busy} onClick={()=>void command({action:'clear-logs'})}>Limpar</button></div></div><div className="terminal"><div className="terminal-head"><span>HORA</span><span title="RX: recebido · TX: enviado · ERR: erro · SYS: sistema">TIPO ⓘ</span><span>EVENTO</span></div>{logs.length?logs.map((l,i)=>{const type=l.message.slice(0,3).trim(),known=['RX','TX','ERR','SYS'].includes(type),shown=known?type:'SYS';return <div className="log-line" key={i}><time>{new Date(l.time).toLocaleTimeString('pt-BR',{hour12:false})}</time><b title={logTypeTitle(shown)} className={shown.toLowerCase()}>{shown}</b><code>{known?l.message.slice(type.length).trim():l.message}</code></div>}):<div className="no-logs">Nenhum evento neste filtro.</div>}</div></section></div>}

function NewMachine({close,created}:{close:()=>void;created:(id:string)=>Promise<void>}){
  const[form,set]=useState({id:'',name:'',port:1505,unitId:1,manufacturer:'generic',model:'generic'}),[busy,setBusy]=useState(false);
  async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);try{const r=await fetch('/api/machines',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});const d=await r.json();if(!r.ok)throw new Error(d.error);await created(d.id)}catch(e){toast((e as Error).message,'error');setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="modal"><div className="panel-title"><div><span className="eyebrow">NOVO ENDPOINT</span><h2>Cadastrar CLP</h2></div><button className="icon-button" onClick={close}>×</button></div><form className="form-grid" onSubmit={submit}><label>Nome da máquina<input required maxLength={80} value={form.name} onChange={e=>set({...form,name:e.target.value})} placeholder="Estação de teste"/></label><label>ID único<input required pattern="[A-Za-z0-9_-]+" value={form.id} onChange={e=>set({...form,id:e.target.value.toLowerCase().replace(/[^a-z0-9_-]/g,'')})} placeholder="estacao_01"/></label><label>Porta TCP<input required type="number" min="1024" max="65535" value={form.port} onChange={e=>set({...form,port:+e.target.value})}/></label><label>Unit ID<input required type="number" min="1" max="247" value={form.unitId} onChange={e=>set({...form,unitId:+e.target.value})}/></label><div className="new-machine-note span-2"><b>Memória manual por padrão</b><span>Depois do cadastro, use a aba Comportamentos para combinar os módulos necessários.</span></div><label>Fabricante<select value={form.manufacturer} onChange={e=>set({...form,manufacturer:e.target.value,model:'generic'})}><option value="generic">Genérico</option><option value="delta">Delta</option><option value="mitsubishi">Mitsubishi</option></select></label><label>Modelo<select disabled value={form.model}><option value="generic">Genérico</option></select><small className="field-help">Modelos específicos serão adicionados futuramente.</small></label><div className="modal-actions"><button type="button" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Cadastrando…':'Cadastrar e conectar'}</button></div></form></div></div>
}

function Faults({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const[form,set]=useState(m.faults);return <div className="content fault-content"><Panel title="Injeção de falhas" extra={<span className={`badge ${Object.values(form).some(Boolean)?'red':'green'}`}>{Object.values(form).some(Boolean)?'ATIVA':'DESATIVADA'}</span>}><form className="fault-grid" onSubmit={e=>{e.preventDefault();void command({action:'faults',...form})}}><label>Perda de pacotes (%)<input type="number" min="0" max="100" step="0.1" value={form.packetLossPercent} onChange={e=>set({...form,packetLossPercent:+e.target.value})}/><small>A requisição não é aplicada nem respondida.</small></label><label>Desconexão aleatória (%)<input type="number" min="0" max="100" step="0.1" value={form.disconnectPercent} onChange={e=>set({...form,disconnectPercent:+e.target.value})}/><small>Encerra as conexões TCP atuais.</small></label><label>Corrupção de leitura (%)<input type="number" min="0" max="100" step="0.1" value={form.corruptReadPercent} onChange={e=>set({...form,corruptReadPercent:+e.target.value})}/><small>Inverte um bit do primeiro valor lido.</small></label><button className="primary" disabled={busy}>Aplicar perfil de falha</button></form></Panel></div>}

function Scenarios({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const empty={id:'',name:'',enabled:true,trigger:'interval' as const,intervalMs:1000,conditionAddress:0,conditionValue:1,targetArea:'register' as const,targetAddress:m.template==='delta-dvp'?4096:0,targetValue:1,lastRunAt:0};const[form,set]=useState<Scenario>(empty);async function save(e:React.FormEvent){e.preventDefault();const id=form.id||`scenario_${Date.now()}`;await command({action:'scenario-save',...form,id});set({...empty,id:'',name:''})}return <div className="content scenario-layout"><Panel title="Editor de cenário" extra={<span className="badge">AUTOMAÇÃO</span>}><form className="form-grid" onSubmit={save}><label className="span-2">Nome<input required value={form.name} onChange={e=>set({...form,name:e.target.value})} placeholder="Alternar sensor de entrada"/></label><label>Disparo<select value={form.trigger} onChange={e=>set({...form,trigger:e.target.value as Scenario['trigger']})}><option value="interval">A cada intervalo</option><option value="register">Quando registrador = valor</option><option value="coil">Quando coil = valor</option></select></label><label>Intervalo (ms)<input type="number" min="250" max="86400000" value={form.intervalMs} onChange={e=>set({...form,intervalMs:+e.target.value})}/></label>{form.trigger!=='interval'&&<><label>Endereço observado<input type="number" min="0" value={form.conditionAddress} onChange={e=>set({...form,conditionAddress:+e.target.value})}/></label><label>Valor esperado<input type="number" min="0" value={form.conditionValue} onChange={e=>set({...form,conditionValue:+e.target.value})}/></label></>}<label>Área de destino<select value={form.targetArea} onChange={e=>set({...form,targetArea:e.target.value as Scenario['targetArea'],targetValue:0})}><option value="register">Holding register</option><option value="coil">Coil</option></select></label><label>Endereço de destino<input type="number" min="0" max={form.targetArea==='coil'?4095:8191} value={form.targetAddress} onChange={e=>set({...form,targetAddress:+e.target.value})}/></label><label>Valor a escrever<input type="number" min="0" max={form.targetArea==='coil'?1:65535} value={form.targetValue} onChange={e=>set({...form,targetValue:+e.target.value})}/></label><label className="switch-line"><input type="checkbox" checked={form.enabled} onChange={e=>set({...form,enabled:e.target.checked})}/><span><b>Cenário habilitado</b><small>Executar automaticamente</small></span></label><button className="primary" disabled={busy}>{form.id?'Atualizar cenário':'Adicionar cenário'}</button></form></Panel><Panel title="Cenários configurados" extra={<span className="badge">{m.scenarios.length}</span>}><div className="scenario-list">{m.scenarios.length?m.scenarios.map(s=><div className="scenario-card" key={s.id}><div><span className={`dot ${s.enabled?'on':'off'}`}/><strong>{s.name}</strong><small>{s.trigger==='interval'?`A cada ${s.intervalMs} ms`:`${s.trigger} ${s.conditionAddress} = ${s.conditionValue}`} → {s.targetArea} {s.targetAddress} = {s.targetValue}</small></div><div><button disabled={busy} onClick={()=>void command({action:'scenario-run',id:s.id})}>Executar</button><button disabled={busy} onClick={()=>void command({action:'scenario-save',...s,enabled:!s.enabled})}>{s.enabled?'Pausar':'Ativar'}</button><button onClick={()=>set({...s})}>Editar</button><button className="danger" disabled={busy} onClick={()=>void command({action:'scenario-delete',id:s.id})}>Excluir</button></div></div>):<div className="no-logs">Nenhum cenário configurado.</div>}</div></Panel></div>}

function History({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){type Metric=keyof Omit<HistoryPoint,'time'>;const[metric,setMetric]=useState<Metric>(m.template==='delta-dvp'?'deltaD0':'register0');const labels:Record<Metric,string>={register0:'Holding 0',register1:'Holding 1',register2:'Holding 2',deltaD0:'Delta D0',coil0:'Coil 0',coil1:'Coil 1',rx:'Requisições RX',tx:'Respostas TX'};const values=m.history.map(p=>p[metric]),min=Math.min(...values,0),max=Math.max(...values,1),span=Math.max(1,max-min);const points=values.map((v,i)=>`${20+(i/Math.max(1,values.length-1))*760},${240-((v-min)/span)*210}`).join(' ');return <div className="content"><section className="chart-panel"><div className="panel-title"><div><h2>Histórico em tempo real</h2><p>Últimas {m.history.length} amostras · até 300 pontos</p></div><div className="log-actions"><select value={metric} onChange={e=>setMetric(e.target.value as Metric)}>{Object.entries(labels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><button disabled={busy} onClick={()=>void command({action:'clear-history'})}>Limpar</button></div></div><div className="chart-wrap"><svg viewBox="0 0 800 260" role="img" aria-label={`Gráfico de ${labels[metric]}`}><line x1="20" y1="240" x2="780" y2="240"/><line x1="20" y1="20" x2="20" y2="240"/><polyline points={points}/><text x="24" y="17">{max}</text><text x="24" y="255">{min}</text></svg>{!values.length&&<div className="chart-empty">O gráfico começará após a primeira amostra de polling.</div>}</div><div className="chart-stats"><Stat label="Atual" value={String(values.at(-1)??0)} sub={labels[metric]}/><Stat label="Mínimo" value={String(min)} sub="Janela atual"/><Stat label="Máximo" value={String(max)} sub="Janela atual"/></div></section></div>}

function download(name:string,type:string,content:string){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),0)}

function EditableStationName({machine,busy,command}:{machine:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const[editing,setEditing]=useState(false),[name,setName]=useState(machine.name);async function save(){const next=name.trim();if(!next){setName(machine.name);setEditing(false);return}if(next!==machine.name)await command({action:'rename',name:next});setEditing(false)}return editing?<form className="station-name-edit" onSubmit={e=>{e.preventDefault();void save()}}><input autoFocus maxLength={80} value={name} onChange={e=>setName(e.target.value)} onBlur={()=>void save()} onKeyDown={e=>{if(e.key==='Escape'){setName(machine.name);setEditing(false)}}}/><button className="primary" disabled={busy||!name.trim()} title="Salvar nome" aria-label="Salvar nome">✓</button></form>:<div className="station-name-view"><h1>{machine.name}</h1><button onClick={()=>setEditing(true)} title="Editar nome da estação" aria-label="Editar nome da estação">✎</button></div>}

function RenameStation({m,busy,command}:{m:Machine;busy:boolean;command:(b:object)=>Promise<any>}){const[name,setName]=useState(m.name);return <div className="content rename-content"><section className="rename-station"><div><span className="eyebrow">IDENTIFICAÇÃO</span><h2>Nome da estação</h2><p>O ID técnico <code>{m.id}</code> permanece inalterado.</p></div><form onSubmit={e=>{e.preventDefault();void command({action:'rename',name})}}><input required maxLength={80} value={name} onChange={e=>setName(e.target.value)} /><button className="primary" disabled={busy||name.trim()===m.name}>Salvar nome</button></form></section></div>}

function ConfirmModal({confirmation,busy,close,execute}:{confirmation:Confirmation;busy:boolean;close:()=>void;execute:()=>Promise<void>}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)close()}}><div className="modal delete-confirm" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><span className="delete-symbol">!</span><h2 id="confirm-title">{confirmation.title}</h2><p>{confirmation.message}</p><div className="modal-actions"><button disabled={busy} onClick={close}>Cancelar</button><button className="danger" disabled={busy} onClick={()=>void execute()}>{busy?'Processando…':confirmation.confirmLabel}</button></div></div></div>}

createRoot(document.getElementById('root')!).render(<App/>);
